#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path
from html.parser import HTMLParser
import json,re
R=Path(__file__).resolve().parent.parent;M=R/'miglik';data=json.loads((M/'site/routes.json').read_text());pages=data['pages']
def write(p,t):
 f=R/'docs'/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(t)
write('architecture/routes.md','# Маршруты\n\nПубличный префикс: /Mini-Brick-Studio/miglik/. Каждая страница — физический index.html.\n\n| Адрес | Title | Индексация |\n|---|---|---|\n'+''.join(f"| {p['path']} | {p['title']} | {'да' if p['index'] else 'нет'} |\n" for p in pages)+'\nФункциональные маршруты — переходы в существующие приложения, не новая реализация корзины/авторизации. /checkout/ ведёт к проверке действующей корзины; приём реальных платежей не добавлен. /account/orders/ ведёт в текущий кабинет; отдельный backend заказов не реализован.\n')
write('architecture/sitemap.md','# Структура\n\nГлавная → Рамки / Миниатюры дома → Примеры, идеи подарков, стоимость, как заказать.\nПодарки → 6 получателей и 5 поводов.\nПодвал → контакты, доставка, FAQ, отзывы, бренд, документы, корзина и кабинет.\n\nКонструктор находится в /Mini-Brick-Studio/studio/. Публичная сборка остаётся статической, без зависимости от серверного fallback.\n')
write('architecture/user-journeys.md','# Пользовательские пути\n\n1. Главная → Рамки → примеры/стоимость → существующий studio.\n2. Главная → Миниатюры дома → план/фото/пожелания → подтверждённый канал ВКонтакте.\n3. Подарки → событие/получатель → продукт → персонализация.\n4. Меню/подвал → Корзина → существующий магазин. Фактическая покупка пока недоступна в демо.\n\nГраница: интерьер не ведёт в редактор минифигурок, а предлагает обсудить проект. Не создаём видимость работающей онлайн-оплаты.\n')
write('seo/metadata-map.md','# Метаданные\n\nДля каждой страницы задан уникальный title, description, canonical, og:title/description/url/image, язык ru, twitter:card. Карта titles — в routes.md и miglik/site/routes.json.\n\n19 индексируемых URL в sitemap.xml; функциональные и юридические черновики noindex,follow. Structured data BreadcrumbList только для реальных ссылок. Не добавлялись вымышленные Product/Offer/AggregateRating.\n')
write('seo/keyword-map.md','# Предварительная карта намерений\n\nРегион не подтверждён. Язык русский. Частотности не измерялись, внешняя семантическая/конкурентная проверка не выполнена. Карта основана на продукте и задании.\n\n| Намерение | Страница |\n|---|---|\n| рамка с минифигурками по фото | ramki-s-minifigurkami |\n| миниатюра квартиры по планировке | miniatura-doma |\n| персональный подарок кому-то | podarki/dlya-* |\n| подарок к событию | podarki/na-* |\n| стоимость подарка | tseny |\n| подготовка заказа | kak-zakazat |\n\nПосадочные различаются поводом, рекомендацией и фотографией, но требуют дальнейшей редакторской оценки ценности до активного SEO-продвижения.\n')
write('seo/technical-seo.md','# Техническое SEO\n\nHTML существует без JS, заголовки семантические. Шаблон проверяется scripts/check-site.py: один H1, последовательность H1/H2/H3, canonical, локальные ссылки. sitemap.xml не содержит приватные и черновые страницы.\n\nGitHub Pages project site не управляет https://alinageminivolsip-ai.github.io/robots.txt: файл внутри проекта не является origin robots. Поэтому noindex задаётся meta robots на функциональных/черновых страницах. Для robots всего домена нужен отдельный root-сайт аккаунта; не создавался.\n\nОбщий og:image сохранён из проекта. Никакие сроки, цены, рейтинги и реквизиты для schema не придуманы. Поисковые инструменты, Search Console и фактическая индексация не проверялись.\n')
assets={}
for f in [M/'index.html']+[M/p['path']/'index.html' for p in pages]:
 for path in re.findall(r'(?:src|poster)="(/Mini-Brick-Studio/miglik/[^"]+)"',f.read_text()):
  key=path.removeprefix('/Mini-Brick-Studio/miglik/');assets.setdefault(key,set()).add(str(f.relative_to(M)))
write('assets/asset-manifest.md','# Использование ассетов\n\nОригиналы не перемещались и не редактировались. Производные WebP используются существующие. Пути — относительно miglik/. Размеры изображений берутся из исходного файла при сборке. Деформации запрещены; object-fit:contain для продуктов, значимые детали не обрезаются.\n\n| Исходный путь (не перемещён) | Страницы | Формат |\n|---|---|---|\n'+''.join(f"| {a} | {', '.join(sorted(ps))} | {Path(a).suffix} |\n" for a,ps in sorted(assets.items()))+'\nАнимационные серии: assets/intro-transparent/intro-v2_*.webp; assets/packaging-sequence-v2/*.webp; editorial/apartment/{small,large}/*.webp (61 кадр). Герои/рамка/коробка и video sources остаются в исходном бандле главной. Новая страница дома использует точную извлечённую реализацию ApartmentPlayer.\n\nШрифты: fonts/onest-*-wght-normal.woff2 и unbounded-*-wght-normal.woff2, лицензии сохранены. Полный список файлов проекта доступен через git ls-files. Неподключённые старые бандлы не удалены: их отсутствие в HTML не доказывает отсутствие runtime-использования.\n')
write('implementation-summary.md','# Реализация\n\nВетка rebuild/multipage-miglik от fd5b185. Существующий сайт расширен генератором Python без npm-зависимостей. Создано 34 внутренних маршрута + главная; 19 индексируемых URL. Общие компоненты header/footer, хлебные крошки, редакционный hero, карточки, FAQ и CTA.\n\nГлавная сохраняет сцены/медиа и добавляет выбор двух направлений; поводы ведут на отдельные страницы. Конструктор и каталог деталей не изменены. Данные корзины/кабинета не мигрировались.\n\nОграничения: реальный checkout, авторизация, правовые условия и цены не придуманы. Юридические тексты — существующие черновики noindex. Для production требуется завершить проверку и подтвердить бизнес-данные. Публикация не выполнялась.\n')
print('Documentation generated.')
